import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        String s = next();
        final long NEG = Long.MIN_VALUE / 4;
        // dp[t]: best population of cities i+1.. when t says whether the unit of city i+1 moves into city i.
        long[] dp = {0, NEG};
        for (int i = n - 1; i >= 0; i--) {
            long[] nxt = {NEG, NEG};
            for (int incoming = 0; incoming < 2; incoming++) {
                if (dp[incoming] == NEG) continue;
                long covered = dp[incoming] + a[i], uncovered = dp[incoming] + (incoming == 1 ? a[i] : 0);
                if (s.charAt(i) == '0') {
                    nxt[0] = Math.max(nxt[0], uncovered);
                } else {
                    nxt[0] = Math.max(nxt[0], covered); // the unit stays
                    if (i > 0) nxt[1] = Math.max(nxt[1], uncovered); // the unit moves left
                }
            }
            dp = nxt;
        }
        System.out.println(dp[0]);
    }
}

