	dp := [2]int{0, neg}
	for i := n - 1; i >= 0; i-- {
		nxt := [2]int{neg, neg}
		for incoming := 0; incoming < 2; incoming++ {
			if dp[incoming] == neg {
				continue
			}
			covered, uncovered := dp[incoming]+a[i], dp[incoming]
			if incoming == 1 {
				uncovered += a[i]
			}
